 private void addMixHero(List<Track> tracks){com.google.android.material.card.MaterialCardView card=UiComponents.card(this,RADIUS_SHEET);LinearLayout body=row();body.setPadding(dp(SPACE_16),dp(SPACE_16),dp(SPACE_16),dp(SPACE_16));body.setMinimumHeight(dp(SIZE_HERO));LinearLayout words=column();TextView eyebrow=caption("MADE FOR YOU");eyebrow.setTextColor(COLOR_ACCENT);words.addView(eyebrow);TextView title=text("Your daily mix",TYPE_SECTION);title.setTypeface(null,android.graphics.Typeface.BOLD);title.setPadding(0,dp(SPACE_8),0,dp(SPACE_4));words.addView(title);TextView hint=caption(tracks.isEmpty()?"Tell us your artists. We’ll find the songs.":tracks.size()+" songs · shaped by your taste");hint.setMaxLines(2);words.addView(hint);words.addView(UiComponents.action(this,tracks.isEmpty()?"Tune my taste":"Play mix",tracks.isEmpty()?R.drawable.ic_lucide_sliders_horizontal:R.drawable.ic_lucide_play,true,()->{if(tracks.isEmpty())showTaste();else playSongCollection(tracks);}));body.addView(words,weight());LinearLayout covers=column();for(int row=0;row<2;row++){LinearLayout pair=row();for(int col=0;col<2;col++){int index=row*2+col;ImageView art=new ImageView(this);art.setScaleType(ImageView.ScaleType.CENTER_CROP);art.setBackground(GlassTheme.coverFrame(this));art.setClipToOutline(true);art.setContentDescription("Mix artwork");if(index<tracks.size())Artwork.load(this,tracks.get(index),art,dp(SIZE_COVER));else art.setImageDrawable(new TrackCoverDrawable(index%2==0?"Pocket":"Music"));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(dp(SIZE_COVER),dp(SIZE_COVER));p.setMargins(dp(SPACE_4),dp(SPACE_4),0,0);pair.addView(art,p);}covers.addView(pair);}LinearLayout.LayoutParams picture=new LinearLayout.LayoutParams(dp(SIZE_HERO_ART),-2);picture.leftMargin=dp(SPACE_12);body.addView(covers,picture);card.addView(body);LinearLayout.LayoutParams margin=new LinearLayout.LayoutParams(-1,-2);margin.topMargin=dp(SPACE_12);margin.bottomMargin=dp(SPACE_4);results.addView(card,margin);}
