  LinearLayout words=column();words.setPadding(dp(SPACE_12),0,dp(SPACE_4),0);TextView title=text(track.title,TYPE_BODY);title.setMaxLines(2);title.setEllipsize(android.text.TextUtils.TruncateAt.END);title.setTypeface(null,android.graphics.Typeface.BOLD);words.addView(title);String detail=track.subtitle();words.addView(caption(localCopies.containsKey(track.id)?"Saved · plays offline":detail.isEmpty()?"YouTube preview":detail));words.setMinimumHeight(dp(SIZE_TOUCH));words.setContentDescription("Play "+track.title);words.setOnClickListener(v->playTrack(track,source));entry.addView(words,weight());
  Button download=ghostButton("↓",()->chooseDownload(track));download.setTextSize(TYPE_SECTION);download.setContentDescription("Download "+track.title);entry.addView(download,new LinearLayout.LayoutParams(dp(SIZE_TOUCH),dp(SIZE_TOUCH)));Button more=ghostButton("⋮",()->onlineTrackMenu(track,source));more.setContentDescription("Song options for "+track.title);entry.addView(more,new LinearLayout.LayoutParams(dp(SIZE_TOUCH),dp(SIZE_TOUCH)));entry.setOnClickListener(v->playTrack(track,source));entry.setBackground(GlassTheme.row(this));return entry;
