 private void pickFolder(){if(folderSaving){message("Let your collection finish saving before changing its folder.");return;}if(DownloadService.busy){message("Let the current download finish before changing its folder.");return;}if(settingsDialog!=null)settingsDialog.dismiss();Intent intent=new Intent(Intent.ACTION_OPEN_DOCUMENT_TREE).addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_WRITE_URI_PERMISSION|Intent.FLAG_GRANT_PERSISTABLE_URI_PERMISSION|Intent.FLAG_GRANT_PREFIX_URI_PERMISSION);Uri old=DownloadFolder.selected(this);if(old!=null)intent.putExtra(android.provider.DocumentsContract.EXTRA_INITIAL_URI,old);startActivityForResult(intent,42);}
 private void syncSavedMusic(boolean afterSelection){
  if(!DownloadFolder.hasAccess(this)){pickFolder();return;}if(folderSaving){message("Saving your collection…");return;}if(DownloadService.busy){message("Let the current download finish, then save your collection.");return;}
  folderSaving=true;List<File> files=MusicRepository.files(this);message("Saving your collection to "+DownloadFolder.label(this)+"…");
  worker.execute(()->{int count=0;String failure="";try{for(File f:files){DownloadFolder.save(this,f);count++;}getSharedPreferences("music",0).edit().remove("folderSaveError").apply();}catch(Exception e){failure="Some files are still in the app. Check your download folder and retry saving.";}final int saved=count;final String error=failure;runOnUiThread(()->{folderSaving=false;if(isDestroyed())return;message(error.isEmpty()?saved+" files saved to "+DownloadFolder.label(this):error);if("library".equals(page))showLibrary();if(afterSelection&&pendingDownload!=null){Track t=pendingDownload;String format=pendingFormat;pendingDownload=null;beginDownload(t,format);} });});
 }
 private void trackMenu(File file){
  List<String> actions=new ArrayList<>(List.of(TrackFiles.audio(file)?"Play":"Open video","Save to download folder","Save a copy elsewhere"));if(TrackFiles.audio(file)){actions.add("Play next");actions.add("Add to queue");}boolean canLike=TrackFiles.audio(file)||MusicTaste.track(this,TrackFiles.videoId(file))!=null;if(canLike)actions.add(MusicTaste.localLiked(this,file)?"Remove from liked songs":"Like song");
  new AlertDialog.Builder(this).setTitle(TrackFiles.title(file)).setItems(actions.toArray(new String[0]),(d,which)->{if(canLike&&which==actions.size()-1){MusicTaste.toggleLocal(this,file);profileChanged();message("Liked songs updated");}else if(which==0)openTrack(file);else if(which==2)export(file);else if(which>=3){LocalPlayerService player=LocalPlayerService.active;if(player==null||streaming){message("Play a saved song first to start a local queue.");return;}message(player.enqueue(file,which==3)?which==3?"Playing next: "+TrackFiles.title(file):"Added to local queue":"This song is already playing.");}else{if(!DownloadFolder.hasAccess(this)){pickFolder();return;}worker.execute(()->{try{DownloadFolder.save(this,file);runOnUiThread(()->message("Saved to "+DownloadFolder.label(this)));}catch(Exception e){runOnUiThread(()->message("Could not save to your folder. Open Settings to choose it again."));}});}}).setNegativeButton("Close",null).show();
 }
 private void openVideo(File file){Uri uri=DownloadFolder.savedUri(this,file);if(uri==null){message("Choose a download folder and save this video there first.");showSettings();return;}try{startActivity(new Intent(Intent.ACTION_VIEW).setDataAndType(uri,"video/mp4").addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION));}catch(Exception e){message("No video player could open this file.");}}
 private void beginDownload(Track track,String format){
  if(!DownloadFolder.hasAccess(this)){pendingDownload=track;pendingFormat=format;pickFolder();return;}
  getSharedPreferences("music",0).edit().putString("lastDownloadId",track.id).putString("lastDownloadTitle",track.title).apply();startForegroundService(new Intent(this,DownloadService.class).putExtra("id",track.id).putExtra("title",track.title).putExtra("format",format));message("");
 }

